import{_ as t,l as s,o as r,c as i,v as l,p as A,x as e,d as n,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"rsLoRA","description":"","frontmatter":{"title":"rsLoRA","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rslora.md","filePath":"llm/rslora.md","lastUpdated":1789023840000}'),h={name:"llm/rslora.md"};function d(E,a,c,B,f,_){const o=s("Mermaid");return r(),i("div",null,[a[1]||(a[1]=l('<h1 id="rslora" tabindex="-1">rsLoRA <a class="header-anchor" href="#rslora" aria-label="Permalink to &quot;rsLoRA&quot;">​</a></h1><div class="epigraph"><p>$\\alpha/r$ 让秩越大、增量越小；改成 $\\alpha/\\sqrt{r}$，不同秩的梯度尺度才大致稳住，扫 $r$ 时不必每次重配学习率。</p><footer>—— Kalajdzievski，A Rank Stabilization Scaling Factor for LoRA-like Fine-Tuning，2023</footer></div><p><a href="/llm/rft-data-loop">SFT 工程</a>收到拒绝采样循环为止。本单元回到参数高效：<a href="/llm/lora">LoRA</a> 原文把缩放写成 \\(\\alpha/r\\)，并建议改 \\(r\\) 时有效步长不必完全重调——实践里并不成立。Kalajdzievski 的 rsLoRA（rank-stabilized LoRA）把缩放改成 \\(1/\\sqrt{r}\\)，针对的就是「加大秩反而学不动」。缺口从数据契约变成<strong>低秩参数化的尺度</strong>。后课 VeRA、GaLore 默认已理解这条修正。不重讲 <a href="/llm/lora">A 随机、B 为零</a> 的初始化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LoRA 前向 \\(y=W_0x+\\gamma BAx\\)。Hu 等人取 \\(\\gamma=\\alpha/r\\)。若 \\(A\\) 的元素方差不随 \\(r\\) 缩，积 \\(BA\\) 的 Frobenius 尺度随 \\(r\\) 涨，\\(\\alpha/r\\) 把它压回去，名义上保持 \\(\\|\\Delta W\\|\\) 量级。问题出在反向：对 \\(A\\)、\\(B\\) 的梯度也含 \\(\\gamma\\)。\\(r\\) 增大时 \\(\\gamma\\) 变小，适配器参数收到的更新幅度下降，表现为「\\(r=64\\) 还不如 \\(r=8\\)」——不是表达力不够，是优化被缩放掐死。</p><p><a href="/llm/lora-vs-full-lr">上一课的学习率分叉</a>已经警告 \\(\\eta\\) 与 \\(\\alpha/r\\) 耦合。rsLoRA 主张：与其每个 \\(r\\) 重扫 \\(\\eta\\)，不如换一个使梯度方差对 \\(r\\) 更稳的 \\(\\gamma\\)。</p><h3 id="稳定的是秩方向上的尺度-不是损失曲面" tabindex="-1">稳定的是秩方向上的尺度，不是损失曲面 <a class="header-anchor" href="#稳定的是秩方向上的尺度-不是损失曲面" aria-label="Permalink to &quot;稳定的是秩方向上的尺度，不是损失曲面&quot;">​</a></h3><p>这不是证明最优 \\(r\\)。它只让不同 \\(r\\) 落在可比的有效学习率上，网格才有意义。仍可能 \\(r\\) 过大过拟合、\\(r\\) 过小欠拟合。</p><p><span class="marginnote">实现里常把 <code>use_rslora=True</code> 当作开关：缩放从 1/r 换成 1/√r。α 的习惯值不能原样迁移，需要按新 γ 重标一次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取 \\(\\gamma=\\alpha/\\sqrt{r}\\)（或等价地把 \\(\\alpha\\) 吸收进学习率，只保留 \\(1/\\sqrt{r}\\)）。其余与 LoRA 相同：插入哪些矩阵、\\(A\\) 高斯、\\(B\\) 零、训练不合并。从旧配方迁移：若原 \\(r=8\\)、\\(\\gamma=\\alpha/8\\) 工作良好，切到 rsLoRA 后令 \\(\\alpha&#39;/\\sqrt{8}\\approx\\alpha/8\\)，再以该点为中心扫 \\(r\\)。不要同时改开关与 \\(\\eta\\) 与 \\(\\alpha\\)。</p>',11)),(r(),A(m,null,{default:e(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20R%5B%22%E6%8F%90%E9%AB%98%E7%A7%A9%20r%22%5D%20--%3E%20OLD%5B%22%CE%B3%3D%CE%B1%2Fr%EF%BC%9A%E6%A2%AF%E5%BA%A6%E5%8F%98%E5%B0%8F%22%5D%0A%20%20R%20--%3E%20NEW%5B%22%CE%B3%3D%CE%B1%2F%E2%88%9Ar%EF%BC%9A%E5%B0%BA%E5%BA%A6%E6%9B%B4%E7%A8%B3%22%5D%0A%20%20OLD%20--%3E%20M%5B%22%E8%AF%AF%E5%88%A4%E4%B8%BA%E6%AC%A0%E6%8B%9F%E5%90%88%22%5D%0A%20%20NEW%20--%3E%20G%5B%22%E7%9C%9F%E6%AD%A3%E6%AF%94%E8%BE%83%E8%A1%A8%E8%BE%BE%E5%8A%9B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>与 <a href="/llm/adalora">AdaLoRA</a> 不同：rsLoRA 不动态分配秩，只改全局缩放。与 DoRA 不同：不拆幅度。它可以和它们叠，但本课单独成立。SFT 仍用<a href="/llm/response-only-loss">仅回复</a>与同一<a href="/llm/chat-template">模板</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>粗略看 \\(BA\\) 的一行：若 \\(A\\) 行近似独立、方差为 \\(\\sigma^2\\)，则 \\(r\\) 项相加后标准差 \\(\\sim\\sigma\\sqrt{r}\\)。除以 \\(r\\) 得到 \\(\\sim 1/\\sqrt{r}\\) 的衰减；除以 \\(\\sqrt{r}\\) 则前向尺度近似与 \\(r\\) 无关。反向对因子的梯度再乘 \\(\\gamma\\)，于是 \\(1/\\sqrt{r}\\) 使「每个秩一分量」分到的更新不随 \\(r\\) 塌缩。这是方差启发式，不是 Transformer 的定理；宽层、不同初始化会偏离。</p><p>经验上，稳定缩放让你把 \\(r\\) 当作容量旋钮：指令任务从 8 加到 32 应看到训练 NLL 下降或持平，而不是神秘上升。若仍上升，再查数据背诵与 \\(\\eta\\)，而不是先怪 LoRA「不行」。</p><p><span class="marginnote">全参没有 γ。不要把 rsLoRA 的大学习率抄回全参——<a href="/llm/lora-vs-full-lr">学习率课</a>仍然有效。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>极小 \\(r\\)（1–2）时 \\(1/r\\) 与 \\(1/\\sqrt{r}\\) 差一截，迁移必须重标 \\(\\alpha\\)。极大 \\(r\\) 接近全参时，低秩假设本身弱，缩放争论次要。QLoRA 存 4-bit 基座，缩放仍作用在 16-bit 适配器上，rsLoRA 同样适用。合并推理时 \\(\\gamma BA\\) 一次加进 \\(W_0\\)，部署不保留「用哪种缩放」的区别，只保留学到的矩阵。</p><p>多适配器服务时，每个适配器自己的 \\(\\gamma\\) 在训练时已经乘进 \\(B,A\\) 或单独存。合并多个适配器见后课<a href="/llm/lora-merge-conflict">LoRA 合并与冲突</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原文 LoRA 的 \\(\\alpha/r\\) 会在大 \\(r\\) 上压小适配器梯度。</li><li>rsLoRA 用 \\(\\alpha/\\sqrt{r}\\)，使扫秩时有效步长更可比。</li><li>改开关必须重标 \\(\\alpha\\)，不要与 \\(\\eta\\) 同时盲改。</li><li>它不分配层间秩，也不提高表达力上限，只稳住优化尺度。</li><li>全参与 LoRA 的 \\(\\eta\\) 分叉仍然成立。</li><li>出处：Kalajdzievski，Rank Stabilization Scaling Factor for LoRA-like Fine-Tuning，2023；基式见 Hu 等，LoRA，2021。</li></ul>',10))])}const L=t(h,[["render",d]]);export{R as __pageData,L as default};
